import 'package:bondhon/core/localization/app_localizations.dart';import 'package:bondhon/features/admin/data/admin_repository.dart';import 'package:bondhon/features/admin/presentation/screens/admin_dashboard_screen.dart';import 'package:flutter/material.dart';import 'package:flutter_test/flutter_test.dart';
void main(){testWidgets('admin dashboard loads and local state update is reflected',(tester)async{final r=AdminRepository();await tester.pumpWidget(MaterialApp(localizationsDelegates:const[AppLocalizations.delegate],supportedLocales:AppLocalizations.supportedLocales,locale:AppLocalizations.englishLocale,home:AdminDashboardScreen(repository:r)));expect(find.text('Admin Dashboard'),findsOneWidget);expect(find.text('Admin demo — mock data only. Not connected to production.'),findsOneWidget);r.setReportStatus('r1',AdminReportStatus.reviewed);await tester.pump();expect(r.openReports,3);});}